  const DEFAULT_CSS = ':root { --accent: #49b6ff; --graph-curve: #49b6ff; --snap: #f6b56d; }\n#editor { background-color: #10151e; }\n.panel { gap: 0px; border-width: 1px; border-opacity: 0.16; focus-opacity: 0.35; border-radius: 0px; }\n.tabs { background-color: #18212e; color: #a8b9cf; height: 32px; }\n.toolbar { height: 42px; }\n.timeline { background-color: #18212e; }\n.button { background-color: #49b6ff; border-radius: 5px; height: 26px; }\n.input { background-color: #101923; border-color: #35475a; border-radius: 5px; }\n.menu { animation-duration: 0.14s; }\n.text { color: #e9f3ff; font-scale: 1.05; }';

  const state = {name:'AK Studio Pro',id:'ak-studio-pro',author:'tu-usuario',version:'1.0.0',base:'StudioBlue',min_version:'2.3.0',description:'Un espacio de edición personalizado para AK Screen.',colors:{...STUDIO_COLORS},metrics:{...DEFAULT_METRICS},clip_colors:{...CLIP_COLORS},asset_colors:{...ASSET_COLORS},groups:structuredClone(DEFAULT_GROUPS),ratios:{vertical:0.58,left:0.33,center:0.65,project:0.28,tools:64,timeline:0.91},workspace:'Studio',cssEnabled:true,css:DEFAULT_CSS,includeCss:true,includePreview:true,previewBgOpacity:38,files:{},icons:[],license:'',previewMode:'editor'};
  const objectUrls = new Set();
  let dirtyTimer, toastTimer, currentSection = 'identity';
  const $ = (id) => document.getElementById(id);

  function esc(value){return String(value).replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function slug(value){return value.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80);}
  function toast(message,error=false){const node=$('toast');node.textContent=message;node.classList.toggle('error',error);node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),3400);}
  function updateName(){const name=$('name').value.trim()||'Tema sin título';$('theme-title').textContent=name;$('inspector-name').textContent=name;document.title=`${name} · Theme Studio`;}
  function saveLocal(){clearTimeout(dirtyTimer);$('saved-state').textContent='Guardando…';dirtyTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(serializeState()));$('saved-state').textContent='Guardado en este navegador';}catch{$('saved-state').textContent='Guardado sin recursos grandes';}},180);}
  function serializeState(){return {...state,files:Object.fromEntries(Object.entries(state.files).map(([key,value])=>[key,{name:value.name,type:value.type,data:value.data}])),icons:state.icons.map(x=>({name:x.name,role:x.role,type:x.type,data:x.data})),license:state.license};}
  async function restoreLocal(){try{const saved=localStorage.getItem(STORAGE_KEY);if(!saved)return;const data=JSON.parse(saved);Object.assign(state,data);state.files={};for(const [key,value] of Object.entries(data.files||{})){state.files[key]={...value,blob:await (await fetch(value.data)).blob()};}state.icons=[];for(const icon of data.icons||[])state.icons.push({...icon,blob:await (await fetch(icon.data)).blob()});}catch{localStorage.removeItem(STORAGE_KEY);}}
  function bindText(id,key,transform){$(id).addEventListener('input',()=>{state[key]=transform?transform($(id).value):$(id).value;if(key==='name')updateName();if(key==='name'&&$('theme-id').dataset.edited!=='true'){$('theme-id').value=slug(state.name);state.id=$('theme-id').value;}refresh();});}

  function addColorRow(host,key,value,kind='main'){
    const row=document.createElement('div');row.className='color-row';row.dataset.color=key;
    const label=document.createElement('label');label.textContent=kind==='main'?(COLOR_LABELS[key]||key):key.replaceAll('_',' ');label.htmlFor=`color-${kind}-${key}`;label.title=key;
    const picker=document.createElement('input');picker.type='color';picker.id=label.htmlFor;picker.value=/^#[\da-f]{6}$/i.test(value)?value:'#888888';picker.setAttribute('aria-label',`Color ${key}`);
    const hex=document.createElement('input');hex.type='text';hex.value=picker.value;hex.maxLength=7;hex.setAttribute('aria-label',`Valor hexadecimal ${key}`);hex.spellcheck=false;
    const set=(v)=>{if(!/^#[\da-f]{6}$/i.test(v))return;picker.value=v;hex.value=v;const target=kind==='main'?state.colors:state[kind];target[key]=v.toLowerCase();refresh();};
    picker.addEventListener('input',()=>set(picker.value));hex.addEventListener('change',()=>set(hex.value.trim()));
    row.append(label,picker,hex);host.append(row);
  }
  function renderColors(){const root=$('color-groups');root.replaceChildren();for(const [title,keys] of COLOR_GROUPS){const group=document.createElement('div');group.className='color-group';const h=document.createElement('h3');h.textContent=title;const grid=document.createElement('div');grid.className='color-grid';for(const key of keys)addColorRow(grid,key,state.colors[key]||STUDIO_COLORS[key]||'#777777');group.append(h,grid);root.append(group);}const clips=$('clip-color-fields');clips.replaceChildren();for(const [key,value] of Object.entries(state.clip_colors))addColorRow(clips,key,value,'clip_colors');const assets=$('asset-color-fields');assets.replaceChildren();for(const [key,value] of Object.entries(state.asset_colors))addColorRow(assets,key,value,'asset_colors');}
  function renderMetrics(){const host=$('metric-fields');host.replaceChildren();for(const [key,label,min,max,step,unit] of METRICS){const value=Number(state.metrics[key]??DEFAULT_METRICS[key]);const row=document.createElement('div');row.className='metric-row';const text=document.createElement('div');text.innerHTML=`<b>${esc(label)}</b><small>${esc(METRIC_HINTS[key])}</small>`;const control=document.createElement('div');control.className='metric-control';const num=document.createElement('input');num.type='number';num.min=min;num.max=max;num.step=step;num.value=Number(value.toFixed(2));num.setAttribute('aria-label',label);const suffix=document.createElement('span');suffix.className='unit';suffix.textContent=unit;const range=document.createElement('input');range.type='range';range.className='range-line';range.min=min;range.max=max;range.step=step;range.value=value;range.setAttribute('aria-label',`${label} slider`);const apply=(v)=>{const n=Number(v);if(!Number.isFinite(n))return;state.metrics[key]=Math.min(max,Math.max(min,n));num.value=String(state.metrics[key]);range.value=String(state.metrics[key]);refresh();};num.addEventListener('change',()=>apply(num.value));range.addEventListener('input',()=>apply(range.value));control.append(num,suffix);row.append(text,control,range);host.append(row);}}
  function renderRatios(){const host=$('layout-ratios');host.replaceChildren();for(const [key,label,min,max,step,unit] of [['vertical','Altura de paneles superiores',0.25,0.78,0.01,'%'],['left','Ancho del panel Source',0.15,0.50,0.01,'%'],['center','Ancho del panel Program',0.25,0.76,0.01,'%'],['project','Ancho del panel Proyecto',0.15,0.48,0.01,'%'],['tools','Ancho de herramientas',40,120,1,'px'],['timeline','Ancho relativo de Timeline',0.65,0.98,0.01,'%']]){const row=document.createElement('div');row.className='layout-ratio';const text=document.createElement('label');text.textContent=label;const range=document.createElement('input');range.type='range';range.min=min;range.max=max;range.step=step;range.value=state.ratios[key];const out=document.createElement('output');const format=()=>unit==='px'?`${Math.round(state.ratios[key])} px`:`${Math.round(state.ratios[key]*100)}%`;out.textContent=format();range.addEventListener('input',()=>{state.ratios[key]=Number(range.value);out.textContent=format();refresh();});row.append(text,range,out);host.append(row);}}
  function renderGroups(){const host=$('panel-groups');host.replaceChildren();for(const [key,title] of [['source','Monitor Source'],['program','Monitor Program'],['properties','Controles / propiedades'],['project','Proyecto / medios'],['timeline','Timeline inferior']]){const group=document.createElement('div');group.className='panel-group';group.dataset.group=key;group.addEventListener('dragover',(e)=>{e.preventDefault();group.classList.add('drag-over');});group.addEventListener('dragleave',()=>group.classList.remove('drag-over'));group.addEventListener('drop',(e)=>{e.preventDefault();group.classList.remove('drag-over');const panel=e.dataTransfer.getData('text/plain');if(panel)movePanel(panel,key);});const head=document.createElement('div');head.className='panel-group-head';head.innerHTML=`<span>${esc(title)}</span><b>${(state.groups[key]||[]).length} tabs</b>`;const chips=document.createElement('div');chips.className='panel-chips';for(const panel of state.groups[key]||[]){const chip=document.createElement('span');chip.className='panel-chip';chip.textContent=PANEL_LABELS[panel]||panel;chip.draggable=true;chip.title=`Arrastra ${PANEL_LABELS[panel]||panel} a otro grupo`;chip.addEventListener('dragstart',(e)=>{chip.classList.add('dragging');e.dataTransfer.setData('text/plain',panel);});chip.addEventListener('dragend',()=>chip.classList.remove('dragging'));chips.append(chip);}group.append(head,chips);host.append(group);}const used=new Set([...Object.values(state.groups).flat(),'Tools','AudioMeters']);const pool=$('available-panels');pool.replaceChildren();for(const panel of ALL_PANELS.filter(x=>!used.has(x))){const chip=document.createElement('span');chip.className='panel-chip pool';chip.textContent=PANEL_LABELS[panel];chip.draggable=true;chip.addEventListener('dragstart',(e)=>e.dataTransfer.setData('text/plain',panel));pool.append(chip);}}
  function movePanel(panel,target){const groupKey=Object.keys(state.groups).find(k=>state.groups[k].includes(panel));if(groupKey===target)return;if(groupKey&&state.groups[groupKey].length<=1){toast('Cada grupo debe conservar al menos un panel.',true);return;}for(const group of Object.values(state.groups)){const idx=group.indexOf(panel);if(idx>=0)group.splice(idx,1);}state.groups[target].push(panel);renderGroups();refresh();}
  function renderAssetPreview(key){const node=$(`${key}-preview`);const file=state.files[key];node.replaceChildren();if(!file){node.textContent=key==='font'?'Fuente del sistema':'Sin imagen';return;}if(key==='font'){node.textContent=file.name;return;}const img=document.createElement('img');img.alt=file.name;img.src=file.url||URL.createObjectURL(file.blob);if(!file.url){file.url=img.src;objectUrls.add(file.url);}node.append(img);}
  function renderIcons(){const host=$('icon-list');host.replaceChildren();if(!state.icons.length){const message=document.createElement('p');message.className='subsection-empty';message.textContent='Aún no hay iconos personalizados.';host.append(message);return;}for(const [i,icon] of state.icons.entries()){const row=document.createElement('div');row.className='icon-row';const img=document.createElement('img');img.src=icon.url||URL.createObjectURL(icon.blob);icon.url=img.src;objectUrls.add(img.src);img.alt='';const role=document.createElement('select');role.setAttribute('aria-label','Nombre de icono nativo');for(const name of ICONS){const option=document.createElement('option');option.value=name;option.textContent=name;option.disabled=state.icons.some((other,index)=>index!==i&&other.role===name);if(name===icon.role)option.selected=true;role.append(option);}role.addEventListener('change',()=>{icon.role=role.value;refresh();});const name=document.createElement('input');name.value=icon.name;name.setAttribute('aria-label','Nombre de archivo SVG');name.addEventListener('change',()=>{icon.name=name.value.replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,80)||'icon';refresh();});const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.title='Eliminar icono';remove.addEventListener('click',()=>{state.icons.splice(i,1);renderIcons();refresh();});row.append(img,role,name,remove);host.append(row);}}
  function setFile(key,file){if(!file){delete state.files[key];renderAssetPreview(key);refresh();return;}const limit=key==='font'?8*1024*1024:16*1024*1024;if(file.size>limit){toast(`El archivo supera el límite de ${key==='font'?'8':'16'} MB.`,true);return;}const allowed=key==='font'?/\.(ttf|otf)$/i.test(file.name):/\.(png|jpe?g|gif|webp)$/i.test(file.name);if(!allowed){toast('Formato de archivo no admitido.',true);return;}const fontName=file.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(-200);const fileName=key==='editor-background'?`assets/backgrounds/editor.${extension(file.name)}`:key==='splash-background'?`assets/backgrounds/splash.${extension(file.name)}`:`assets/fonts/${fontName}`;const reader=new FileReader();reader.onload=()=>{state.files[key]={name:file.name,type:file.type,blob:file,data:reader.result,path:fileName};renderAssetPreview(key);refresh();};reader.onerror=()=>toast('No se pudo leer el archivo.',true);reader.readAsDataURL(file);}
  function extension(name){return name.split('.').pop().toLowerCase().replace('jpeg','jpg');}
  function safeSvgDocument(doc,text){if(doc.querySelector('parsererror')||text.includes('<!DOCTYPE')||text.includes('<!ENTITY')||/\{[A-Za-z_][A-Za-z_0-9]*\}/.test(text))return false;const nodes=[...(doc.documentElement?.querySelectorAll('*')||[])];return nodes.length<=2000&&nodes.every(node=>!['script','foreignObject','style'].includes(node.localName)&&[...node.attributes].every(attr=>!/^on/i.test(attr.name)&&!/(?:url\s*\(|javascript:)/i.test(attr.value)&&(!['href','src'].includes(attr.localName.toLowerCase())||attr.value.startsWith('#'))));}
